// Real beacon information elements from Keith's UniFi AP, channel 108.
//
// Captured 25 OCT 2026 by WLAN Pi "shannon" (wlanpi0, monitor mode, 5540 MHz),
// one beacon per BSSID, with the Keith Guest SSID in OWE Transition mode. Each
// string is the tagged-parameter block only (after the 24-byte MAC header and
// the 12 fixed bytes), which is what CoreWLAN's `informationElementData`
// carries. The Pi's own decode of the same capture agreed: b2 OWE / CCMP-128 /
// PMF required, a2 Open, 9c WPA3 SAE.

import 'dart:typed_data';

Uint8List hexBytes(String hex) => Uint8List.fromList(<int>[
      for (int i = 0; i < hex.length; i += 2)
        int.parse(hex.substring(i, i + 2), radix: 16),
    ]);

